  "# TODO: def raises(func, error):\n\n\nprint(raises(lambda: int('x'), ValueError))\nprint(raises(lambda: int('5'), ValueError))",
  "def raises(func, error):\n    try:\n        func()\n    except error:\n        return True\n    return False\n\nprint(raises(lambda: int('x'), ValueError))\nprint(raises(lambda: int('5'), ValueError))",
  "def raises(func, error):\n    try:\n        func()\n    except error:\n        return True\n    return False",
